export const UsersPageActions = createActionGroup({
  source: 'Users Page',
  events: {
    'Opened': emptyProps(),
    'Search Changed': props<{ query: string }>(),
  },
});
// komponent
this.store.dispatch(UsersPageActions.searchChanged({ query: 'ala' }));
users = this.store.selectSignal(selectFilteredUsers);

export const usersReducer = createReducer(
  initialState,
  on(UsersPageActions.searchChanged, (state, { query }) => ({ ...state, query })),
  on(UsersApiActions.loadSuccess, (state, { users }) => ({
    ...state, users, loading: false,
  })),
);

export const selectUsersState = createFeatureSelector<UsersState>('users');
export const selectUsers = createSelector(selectUsersState, s => s.users);
export const selectQuery = createSelector(selectUsersState, s => s.query);
export const selectFilteredUsers = createSelector(
  selectUsers, selectQuery,
  (users, q) => users.filter(u => u.name.includes(q)),
);

export const usersFeature = createFeature({
  name: 'users',
  reducer: usersReducer,
  extraSelectors: ({ selectUsers, selectQuery }) => ({
    selectFiltered: createSelector(selectUsers, selectQuery,
      (users, q) => users.filter(u => u.name.includes(q))),
  }),
});
// routes: { path: 'users', providers: [provideState(usersFeature),
//   provideEffects(usersEffects)], loadComponent: ... }

export const loadUsers = createEffect(
  (actions$ = inject(Actions), api = inject(UsersApi)) =>
    actions$.pipe(
      ofType(UsersPageActions.opened),
      switchMap(() => api.getAll().pipe(
        map(users => UsersApiActions.loadSuccess({ users })),
        catchError(error => of(UsersApiActions.loadFailure({ error: error.message }))),
      )),
    ),
  { functional: true },
);
// rejestracja: provideEffects(usersEffects)  // import * as usersEffects

// ŹLE – po pierwszym błędzie effect przestaje działać
