  map(() => saveSuccess()), catchError(e => of(saveFailure(e))));
// DOBRZE
actions$.pipe(ofType(save), concatMap(a => api.save(a.item).pipe(
  map(() => saveSuccess()),
  catchError(e => of(saveFailure({ error: e.message }))),
)));

export const adapter = createEntityAdapter<User>({
  sortComparer: (a, b) => a.name.localeCompare(b.name),
});
const initialState = adapter.getInitialState({ loading: false });
export const reducer = createReducer(initialState,
  on(UsersApiActions.loadSuccess, (s, { users }) => adapter.setAll(users, { ...s, loading: false })),
  on(UserActions.renamed, (s, { id, name }) => adapter.updateOne({ id, changes: { name } }, s)),
);
const { selectAll, selectEntities } = adapter.getSelectors();

@Injectable({ providedIn: 'root' })
export class UsersFacade {
  private store = inject(Store);
  readonly users = this.store.selectSignal(usersFeature.selectFiltered);
  readonly loading = this.store.selectSignal(usersFeature.selectLoading);
  opened() { this.store.dispatch(UsersPageActions.opened()); }
  search(query: string) { this.store.dispatch(UsersPageActions.searchChanged({ query })); }
}

