export class PriceComponent implements OnChanges {
  @Input({ required: true }) amount!: number;
  @Input() currency = 'PLN';
  @Output() selected = new EventEmitter<number>();
  formatted = '';
  ngOnChanges(changes: SimpleChanges) {
    if (changes['amount'] || changes['currency']) {
      this.formatted = `${this.amount} ${this.currency}`;
    }
  }
}

private zone = inject(NgZone);
ngOnInit() {
  this.zone.runOutsideAngular(() => {
    fromEvent<MouseEvent>(this.el.nativeElement, 'mousemove').pipe(
      throttleTime(100),
    ).subscribe(e => this.zone.run(() => this.pos.set([e.x, e.y])));
  });
}

